const e=JSON.parse('{"key":"v-d6cfdd6e","path":"/%E5%BE%AE%E5%89%8D%E7%AB%AF/single-spa/single-spa%E5%9F%BA%E7%A1%80.html","title":"single-spa基础","lang":"zh-CN","frontmatter":{"title":"single-spa基础","date":"2024-06-07T16:13:03.000Z","order":1,"category":["前端","学习笔记","微前端"],"tag":["微前端","single-spa"],"description":"single-spa 基础 single-spa 是一个将多个单页面应用聚合为一个整体应用的 JavaScript 微前端框架。 实现方法 single-spa 提供了一种基于路由的基座化的微前端方案，它将应用分为两类：基座应用和子应用。其中，子应用对应需要聚合的应用，基座应用是另外一个单独的应用，用于聚合子应用。 在基座应用中，我们会维护一个路由注册表 - 每个路由对应一个子应用。基座应用启动以后，当我们切换路由时，如果是一个新的子应用，会动态获取子应用的 js 脚本，然后执行脚本并渲染出相应的页面；如果是一个已经访问过的子应用，那么就会从基座应用的缓存中获取已经缓存的子应用，激活子应用并渲染出对应的页面。","head":[["meta",{"property":"og:url","content":"https://mister-hope.github.io/blog/%E5%BE%AE%E5%89%8D%E7%AB%AF/single-spa/single-spa%E5%9F%BA%E7%A1%80.html"}],["meta",{"property":"og:site_name","content":"tang’blog"}],["meta",{"property":"og:title","content":"single-spa基础"}],["meta",{"property":"og:description","content":"single-spa 基础 single-spa 是一个将多个单页面应用聚合为一个整体应用的 JavaScript 微前端框架。 实现方法 single-spa 提供了一种基于路由的基座化的微前端方案，它将应用分为两类：基座应用和子应用。其中，子应用对应需要聚合的应用，基座应用是另外一个单独的应用，用于聚合子应用。 在基座应用中，我们会维护一个路由注册表 - 每个路由对应一个子应用。基座应用启动以后，当我们切换路由时，如果是一个新的子应用，会动态获取子应用的 js 脚本，然后执行脚本并渲染出相应的页面；如果是一个已经访问过的子应用，那么就会从基座应用的缓存中获取已经缓存的子应用，激活子应用并渲染出对应的页面。"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2024-06-18T02:29:05.000Z"}],["meta",{"property":"article:author","content":"唐皓晨"}],["meta",{"property":"article:tag","content":"微前端"}],["meta",{"property":"article:tag","content":"single-spa"}],["meta",{"property":"article:published_time","content":"2024-06-07T16:13:03.000Z"}],["meta",{"property":"article:modified_time","content":"2024-06-18T02:29:05.000Z"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"single-spa基础\\",\\"image\\":[\\"\\"],\\"datePublished\\":\\"2024-06-07T16:13:03.000Z\\",\\"dateModified\\":\\"2024-06-18T02:29:05.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"唐皓晨\\",\\"url\\":\\"https://github.com/2290774104/blog\\"}]}"]]},"headers":[{"level":2,"title":"实现方法","slug":"实现方法","link":"#实现方法","children":[]},{"level":2,"title":"single-spa 项目模板","slug":"single-spa-项目模板","link":"#single-spa-项目模板","children":[]}],"git":{"createdTime":1718677745000,"updatedTime":1718677745000,"contributors":[{"name":"2290774104","email":"2290774104@qq.com","commits":1}]},"readingTime":{"minutes":1.06,"words":318},"filePathRelative":"微前端/single-spa/single-spa基础.md","localizedDate":"2024年6月8日","excerpt":"<h1> single-spa 基础</h1>\\n<p>single-spa 是一个将多个单页面应用聚合为一个整体应用的 JavaScript 微前端框架。</p>\\n<h2> 实现方法</h2>\\n<p>single-spa 提供了一种基于路由的基座化的微前端方案，它将应用分为两类：基座应用和子应用。其中，子应用对应需要聚合的应用，基座应用是另外一个单独的应用，用于聚合子应用。</p>\\n<p>在基座应用中，我们会维护一个路由注册表 - 每个路由对应一个子应用。基座应用启动以后，当我们切换路由时，如果是一个新的子应用，会动态获取子应用的 js 脚本，然后执行脚本并渲染出相应的页面；如果是一个已经访问过的子应用，那么就会从基座应用的缓存中获取已经缓存的子应用，激活子应用并渲染出对应的页面。</p>","autoDesc":true}');export{e as data};
